"""Bundle schema — the data model behind the agent artifact contract.

The whole bundle is one JSON document (``AgentBundleManifest``) plus the
payload files it references by SHA-256. Keeping the manifest self-contained
is deliberate: a verifier that only has the manifest (e.g. a registry mirror
or a CISO's offline air-gapped box) can still answer "is this bundle
*structurally* sound?" without fetching payload bytes.

Models (pydantic v2, extra-key-fidding, slug-validated):

- ``AgentBundleManifest`` — top level. Pins the spec version, identity
  (publisher key hint + agent id), and a manifest of components.
- ``AgentComponent``      — one of:
      * ``system_prompt``   — plain text, byte-hashed.
      * ``tool``            — WASM module + declared host imports it wants.
      * ``memory_contract`` — schema for the agent's state read/writes across
                              turns (key -> shape + write policy).
      * ``permission_policy`` — capability policy (see sandbox.capabilities);
                              the *only* policy source the sandbox trusts.
      * ``eval_suite``      — list of named eval cases: input, expected
                              observable, and the budget they may spend.
- ``FileRef``             — ``{path, sha256, bytes}``. Every payload file
  appears here exactly once.
- ``MemoryContractField`` — a single addressable slot. ``write_policy``
  is one of ``append_only`` | ``replace`` | ``sealed_after_n_writes`` —
  this is also the surface auditors care about: it names what the agent
  is *allowed to change about itself*.

Design rules encoded by these models:
- All versions in string form (semver). ``spec_version`` is what changes
  the format; it is the only field a verifier may need to branch on.
- IDs are URI-safe slugs. No free-form strings where an ID is expected.
- ``FileRef.sha256`` is computed by the packager, never trusted from
  caller inputs — a caller-supplied hash is treated as an assertion the
  packager must re-verify before signing.
- Equality is *content* equality (hash-based), ignoring file ordering.
  This is what makes signatures deterministic and the portability diff
  (step 4) meaningful.

Serialization (§2, §4, §10 of spec/agent-bundle-v0.md):
- ``canonical_json`` produces the one encoding every signature is taken
  over: canonical JSON (UTF-8, no BOM, codepoint-sorted keys, no
  insignificant whitespace, shortest-exact numbers, NFC strings). Both
  the packager (signer) and the validator (verifier) must agree on it.
"""

from __future__ import annotations

import json
import re
from enum import Enum
from typing import Optional

from pydantic import BaseModel, Field, field_validator, model_validator

# --------------------------------------------------------------------------- #
# Constraints (kept as compiled modules so the regex lives in one place).     #
# --------------------------------------------------------------------------- #

# §4: agent_id is a URI slug, optionally path-qualified: acme/copywriter.
_AGENT_ID_RE = re.compile(r"^[a-z0-9_-]+(/[a-z0-9_-]+)*$")
# §4: component id — same shape, used for prompt/main, tool/fetch, …
_COMPONENT_ID_RE = re.compile(r"^[a-z0-9_-]+(/[a-z0-9_-]+)*$")
# §4: publisher is a key *hint*, not a key. `keyhint:<name>` where name is a
# token (we are loose here on purpose — it is informational, never trusted).
_KEY_HINT_RE = re.compile(r"^keyhint:[a-z0-9_][a-z0-9_-]*$")
# §4.2 R3-ish: file paths must be slash-joined, never absolute, never contain
# ".." or leading/trailing slashes.
_FILE_PATH_RE = re.compile(r"^[a-z0-9_][a-z0-9_.-]*(?:/[a-z0-9_][a-z0-9_.-]*)*$")
# A 64-char-hex SHA-256, as the spec always shows in files[].sha256.
_SHA256_RE = re.compile(r"^[a-f0-9]{64}$")

# §11: the set of spec_version majors this runtime understands. v0 only.
VALID_SPEC_VERSIONS = frozenset({"0"})

# §4.1: free-text notes are display-only and capped at 4 KiB so a hostile
# bundle cannot smuggle megabytes into the manifest.
_NOTES_MAX_BYTES = 4 * 1024


class WritePolicy(str, Enum):
    """Closed set of self-modification surfaces (§8)."""

    append_only = "append_only"
    replace = "replace"
    sealed_after_n_writes = "sealed_after_n_writes"


class ComponentKind(str, Enum):
    """Closed set of component kinds (§4.1)."""

    system_prompt = "system_prompt"
    tool = "tool"
    memory_contract = "memory_contract"
    permission_policy = "permission_policy"
    eval_suite = "eval_suite"


class FileRef(BaseModel):
    """``{path, sha256, bytes}`` — one payload file, keyed by content."""

    model_config = {"extra": "forbid", "str_to_enum": False}

    path: str = Field(alias="path")
    sha256: str = Field(alias="sha256")
    # JSON key is literally "bytes"; pydantic stores it as attr `.bytes`.
    bytes: int = Field(alias="bytes")

    @field_validator("path")
    @classmethod
    def _path_is_safe(cls, v: str) -> str:
        if not _FILE_PATH_RE.match(v):
            raise ValueError(
                f"file path is not a safe slash-joined slug: {v!r} (R1: no "
                "absolute paths, no '..', no symlinks)"
            )
        return v

    @field_validator("sha256")
    @classmethod
    def _sha256_is_hex(cls, v: str) -> str:
        if not _SHA256_RE.match(v):
            raise ValueError(f"sha256 is not 64 lowercase hex chars: {v!r}")
        return v


class MemoryContractField(BaseModel):
    """One addressable slot in the memory contract (§8)."""

    model_config = {"extra": "forbid"}

    key: str = Field(alias="key")
    shape: str = Field(alias="shape")
    write_policy: WritePolicy = Field(alias="write_policy")
    max_writes: Optional[int] = Field(alias="max_writes", default=None)

    @model_validator(mode="after")
    def _writable(self) -> "MemoryContractField":
        if self.write_policy is WritePolicy.sealed_after_n_writes:
            if self.max_writes is None or self.max_writes <= 0:
                raise ValueError(
                    "sealed_after_n_writes requires max_writes >= 1"
                )
        else:
            if self.max_writes is not None:
                raise ValueError(
                    "max_writes is only meaningful with "
                    "write_policy=sealed_after_n_writes"
                )
        return self


class AgentComponent(BaseModel):
    """One addressed unit inside a bundle (§4)."""

    model_config = {"extra": "forbid"}

    cid: str = Field(alias="cid")
    kind: ComponentKind = Field(alias="kind")
    file: FileRef = Field(alias="file")
    notes: Optional[str] = Field(alias="notes", default=None)

    # tool-only fields; present but ignored for other kinds.
    declared_imports: Optional[list[str]] = Field(
        alias="declared_imports", default=None
    )
    entry_export: Optional[str] = Field(alias="entry_export", default=None)

    @field_validator("cid")
    @classmethod
    def _cid_is_slug(cls, v: str) -> str:
        if not _COMPONENT_ID_RE.match(v):
            raise ValueError(f"component cid is not a safe slug: {v!r}")
        return v

    @field_validator("notes")
    @classmethod
    def _notes_len(cls, v: Optional[str]) -> Optional[str]:
        if v is not None and len(v.encode("utf-8")) > _NOTES_MAX_BYTES:
            raise ValueError(f"notes exceed 4 KiB: {len(v)} chars")
        return v

    @model_validator(mode="after")
    def _tool_fields_consistent(self) -> "AgentComponent":
        is_tool = self.kind is ComponentKind.tool
        if is_tool:
            if not self.declared_imports:
                raise ValueError("tool component must declare declared_imports")
            for imp in self.declared_imports:
                if not isinstance(imp, str) or "/" not in imp:
                    raise ValueError(f"declared_imports entry must be like 'agpack/x.y': {imp!r}")
            if not self.entry_export:
                raise ValueError("tool component must declare an entry_export")
        else:
            if self.declared_imports is not None:
                raise ValueError(f"{self.kind.value} components cannot declare imports")
            if self.entry_export is not None:
                raise ValueError(f"{self.kind.value} components cannot declare entry_export")
        return self


class SignatureBlock(BaseModel):
    """§10: the signing record embedded in the manifest.

    Stores scheme name, public-key bytes, signature bytes, and a
    1s-granularity timestamp. These are *trust* inputs to the validator,
    not free-form text.
    """

    model_config = {"extra": "forbid"}

    scheme: str = Field(alias="scheme")
    public_key: str = Field(alias="public_key")
    signature: str = Field(alias="signature")
    signed_at_unix: int = Field(alias="signed_at_unix")

    @field_validator("scheme")
    @classmethod
    def _scheme_known(cls, v: str) -> str:
        if v != "ed25519":
            raise ValueError(f"unsupported scheme: {v!r} (v0 supports 'ed25519')")
        return v


class AgentBundleManifest(BaseModel):
    """Top-level: the JSON document that travels inside the bundle (§4)."""

    model_config = {"extra": "forbid", "populate_by_name": True}

    spec_version: str = Field(alias="spec_version")
    agent_id: str = Field(alias="agent_id")
    publisher: str = Field(alias="publisher")
    created_at_unix: int = Field(alias="created_at_unix")
    components: tuple[AgentComponent, ...] = Field(alias="components")
    files: tuple[FileRef, ...] = Field(alias="files")
    sign: Optional[SignatureBlock] = Field(alias="sign", default=None)

    @field_validator("spec_version")
    @classmethod
    def _spec_version_supported(cls, v: str) -> str:
        if v not in VALID_SPEC_VERSIONS:
            raise ValueError(
                f"spec_version {v!r} not understood; upgrade the runtime "
                f"(understood: {sorted(VALID_SPEC_VERSIONS)})"
            )
        return v

    @field_validator("agent_id")
    @classmethod
    def _agent_id_is_slug(cls, v: str) -> str:
        if not _AGENT_ID_RE.match(v):
            raise ValueError(f"agent_id is not a URI slug: {v!r}")
        return v

    @field_validator("publisher")
    @classmethod
    def _publisher_is_hint(cls, v: str) -> str:
        if not _KEY_HINT_RE.match(v):
            raise ValueError(f"publisher must be a key hint like 'keyhint:root-1': {v!r}")
        return v

    @field_validator("created_at_unix")
    @classmethod
    def _created_is_second_granularity(cls, v: int) -> int:
        if v <= 0:
            raise ValueError("created_at_unix must be a positive unix timestamp")
        if v % 1_000_000_000_000_000_000 != v:  # unreachable guard; keeps intent clear
            raise ValueError("created_at_unix must be integer seconds")
        return v

    @model_validator(mode="after")
    def _structural(self) -> "AgentBundleManifest":
        # D2: components uniquely identified by cid.
        cids = [c.cid for c in self.components]
        if len(cids) != len(set(cids)):
            raise ValueError("duplicate component cid in manifest")
        # D2: files uniquely identified by path.
        paths = [f.path for f in self.files]
        if len(paths) != len(set(paths)):
            raise ValueError("duplicate file path in manifest")
        # Every component file must resolve to a files[] entry (§4.2 step 5).
        file_paths = {f.path for f in self.files}
        for comp in self.components:
            if comp.file.path not in file_paths:
                raise ValueError(
                    f"component {comp.cid!r} references {comp.file.path!r} "
                    "absent from files[]"
                )
        return self

    # ---- ordering (D2) ---------------------------------------------------- #

    def with_deterministic_order(self) -> "AgentBundleManifest":
        """Return a copy with components by cid and files by (path, sha256)."""

        self_copy = AgentBundleManifest.model_validate(
            {
                **self.model_dump(),
                "components": sorted(self.components, key=lambda c: c.cid),
                "files": sorted(self.files, key=lambda f: (f.path, f.sha256)),
            }
        )
        return self_copy

    # ---- serialization (§4.2, §10) ---------------------------------------- #

    def canonical_json(self) -> bytes:
        """Canonical-JSON bytes. Used verbatim by both signer and verifier.

        ``sign`` is included *as present*: the packager clears it to null,
        signs, then re-sets it (§10).
        """

        return canonical_json(self.with_deterministic_order().model_dump(by_alias=True))

    def canonical_json_without_sign(self) -> bytes:
        """Canonical bytes with ``sign`` explicitly null (§10 signed message).

        The caller clears ``sign`` to null, signs, then re-sets it: this must
        therefore emit a *different* byte stream than ``canonical_json``.
        """

        dumped = self.with_deterministic_order().model_dump(by_alias=True)
        dumped["sign"] = None
        return canonical_json(dumped)


# --------------------------------------------------------------------------- #
# Canonical JSON — the one encoding the whole project signs over.             #
# --------------------------------------------------------------------------- #
# §4.1-4.2 / D1: UTF-8, no BOM, codepoint-sorted keys at every level, no
# insignificant whitespace, shortest-exact number representation, NFC strings.
# Python's json.dumps already emits shortest-exact numbers and sort_keys gives
# codepoint order; ensure_ascii=False keeps NFC unicode compact.
import unicodedata  # noqa: E402


def _nfc(value: object) -> object:
    """Recursively normalize every string to Unicode NFC form."""

    if isinstance(value, str):
        return unicodedata.normalize("NFC", value)
    if isinstance(value, dict):
        return {k: _nfc(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_nfc(v) for v in value]
    return value


def canonical_json(obj: object) -> bytes:
    """Serialize ``obj`` to the bundle's canonical JSON byte encoding."""

    text = json.dumps(
        _nfc(obj),
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )
    return text.encode("utf-8")


def canonical_loads(data: bytes) -> object:
    """Parse canonical JSON back to a Python object (validator helper)."""

    return json.loads(data.decode("utf-8"))
